import logging
import random
import re

from taf.ue.android.exceptions import NoFreePortException, CannotExtractLocalAddress
from taf.ue.android.utils.ue_pc_logger import LoggerAdapter4EmptyExtra

DEFAULT_PORT_MIN = 50000
DEFAULT_PORT_MAX = 60000
DEFAULT_PORT_SEARCH_ATTEMPTS = 100


class FreeTcpPortFinder:
    """Used to find free port to be used by iperf"""

    _logger = LoggerAdapter4EmptyExtra(logging.getLogger('ute_ue.ue'), {'layer': 'DATATRANSFER'})

    @staticmethod
    def is_port_free_in_netstat(netstat_output, port):
        try:
            FreeTcpPortFinder._logger.debug("Trying to check port availability by extracting local addresses.")
            return all(f':{port} ' not in line for line in FreeTcpPortFinder.get_local_address_from_netstat_output(netstat_output))
        except Exception as e:
            FreeTcpPortFinder._logger.debug("Cannot extract local address from netstat output. "
                                            "Extracting from raw output. Error message: " + str(e))
            return all(f':{port} ' not in line for line in netstat_output)

    @staticmethod
    def find_random_free_port(min_port, max_port, attempts, port_validator=lambda port: True):
        """Searches free tcp port.
        :param port_validator: Port validation function, returns boolean which indicates if port is free
        :param min_port: Minimal port value to search
        :param max_port: Maximal port value to search
        :param attempts: Number of tries to find free port before raise an exception
        """
        FreeTcpPortFinder._logger.debug(f"Starting free port search in range {min_port}-{max_port}.")
        for i in range(attempts):
            port = random.randint(min_port, max_port)
            is_port_free = port_validator(port)
            FreeTcpPortFinder._logger.debug(f"Search attempt {i}. Port {port} is "
                                            f"{'free' if is_port_free else 'already in use'}.")
            if is_port_free:
                return port
        raise NoFreePortException(f"No free port was found in {attempts} attempts")

    @staticmethod
    def get_local_address_from_netstat_output(netstat_output):
        """
        Extracts local addresses from netstat output
        :param netstat_output: list of strings representing netstat command output
        :return: list of local addresses
        """
        _net_parser = re.compile(
            r"(?P<PROTO>\S+)\s+(?P<RECVQ>\S+)\s+(?P<SENDQ>\S+)\s+(?P<LADDR>\S+)\s+(?P<FADDR>\S+)\s+(?P<STATE>\S+)")
        f_addr = []
        for line in netstat_output:
            match = re.search(_net_parser, line)
            if match and match.group("PROTO").lower() in ["udp", "tcp", "tcp6", "tcp6"]:
                f_addr.append(match.group('LADDR'))
        if len(f_addr) == 0:
            raise CannotExtractLocalAddress(
                "Cannot extract local address from netstat output. It may be unsupported netstat version.")
        FreeTcpPortFinder._logger.debug(f"Extracted local addresses: {f_addr}")
        return f_addr
